\begin{question}
  \label{qmeasurability} Let $V$ be a model of \textsf{AD}, and let $G$ be $V$-generic for $\mathbb{M}_{\aleph_1\aleph_2}$.
  \begin{enumerate}
    \item [$(\aleph)$] Is $\aleph_{\omega+1}$ a measurable cardinal in $V[G]$?
    \item [$(\beth)$] Is the collection of $\omega$-closed unbounded subsets of $\aleph_{\omega+1}$ a normal ultrafilter in $V[G]$?
  \end{enumerate}
\end{question}

